275  rnp_result_t
   276  transferable_key_merge(pgp_transferable_key_t *dst, const pgp_transferable_key_t *src)
   277  {
   278      rnp_result_t ret = RNP_ERROR_GENERIC;
   279
   280      if (!key_pkt_equal(&dst->key, &src->key, true)) {
   281          RNP_LOG("wrong key merge call");
   282          return RNP_ERROR_BAD_PARAMETERS;
   283      }
   284      /* direct-key signatures */
   285      if ((ret = merge_signatures(&dst->signatures, &src->signatures))) {
   286          RNP_LOG("failed to merge signatures");
   287          return ret;
   288      }
   289      /* userids */
   290      for (list_item *li = list_front(src->userids); li; li = list_next(li)) {
   291          pgp_transferable_userid_t *luid = (pgp_transferable_userid_t *) li;
   292          pgp_transferable_userid_t *userid = transferable_key_has_userid(dst, &luid->uid);
   293          if (userid) {
   294              if ((ret = transferable_userid_merge(userid, luid))) {
   295                  RNP_LOG("failed to merge userid");
   296                  return ret;
   297              }
   298              continue;
   299          }
   300          /* add userid */
   301          userid =
   302            (pgp_transferable_userid_t *) list_append(&dst->userids, NULL, sizeof(*userid));
   303          if (!userid || !transferable_userid_copy(userid, luid)) {
   304              list_remove((list_item *) userid);
   305              return RNP_ERROR_OUT_OF_MEMORY;
   306          }
   307      }
   308
   309      /* subkeys */
   310      for (list_item *li = list_front(src->subkeys); li; li = list_next(li)) {
   311          pgp_transferable_subkey_t *lskey = (pgp_transferable_subkey_t *) li;
   312          pgp_transferable_subkey_t *subkey = transferable_key_has_subkey(dst, &lskey->subkey);
   313          if (subkey) {
   314              if ((ret = transferable_subkey_merge(subkey, lskey))) {
   315                  RNP_LOG("failed to merge subkey");
   316                  return ret;
   317              }
   318              continue;
   319          }
   320          /* add subkey */
   321          if (is_public_key_pkt(dst->key.tag) != is_public_key_pkt(lskey->subkey.tag)) {
   322              RNP_LOG("warning: adding public/secret subkey to secret/public key");
   323          }
   324          subkey =
   325            (pgp_transferable_subkey_t *) list_append(&dst->subkeys, NULL, sizeof(*subkey));
   326          if (!subkey || !transferable_subkey_copy(subkey, lskey, false)) {
   327              list_remove((list_item *) subkey);
   328              return RNP_ERROR_OUT_OF_MEMORY;
   329          }
   330      }
   331
   332      return RNP_SUCCESS;
   333  }
