   335  pgp_transferable_userid_t *
   336  transferable_key_add_userid(pgp_transferable_key_t *key, const char *userid)
   337  {
   338      pgp_userid_pkt_t           uid = {};
   339      pgp_transferable_userid_t *tuid = NULL;
   340
   341      uid.tag = PGP_PKT_USER_ID;
   342      uid.uid_len = strlen(userid);
   343      if (!(uid.uid = (uint8_t *) malloc(uid.uid_len))) {
   344          return NULL;
   345      }
   346      memcpy(uid.uid, userid, uid.uid_len);
   347
   348      tuid = (pgp_transferable_userid_t *) list_append(&key->userids, NULL, sizeof(*tuid));
   349      if (!tuid) {
   350          free(uid.uid);
   351          return NULL;
   352      }
   353
   354      memcpy(&tuid->uid, &uid, sizeof(uid));
   355      return tuid;
   356  }
